choose.when:
SELECT c.company_id AS scope_id, c.company_id
FROM wms_company c
WHERE c.company_id = #{scopeId}

SELECT w.warehouse_id AS scope_id, w.company_id, w.warehouse_id
FROM wms_warehouse w
WHERE w.warehouse_id = #{scopeId}

mapper.select:
SELECT FROM wms_storage s JOIN wms_warehouse w ON w.warehouse_id = s.warehouse_id JOIN wms_company c ON c.company_id = w.company_id JOIN wms_warehouse_zone dz ON dz.zone_id = s.zone_id WHERE s.storage_id IN
#{storageId}
ORDER BY s.storage_id

SELECT c.company_id, c.lifecycle_status AS company_lifecycle_status FROM wms_company c WHERE c.company_id IN
#{companyId}
ORDER BY c.company_id FOR SHARE

SELECT w.warehouse_id, w.company_id AS warehouse_company_id, w.lifecycle_status AS warehouse_lifecycle_status FROM wms_warehouse w WHERE w.warehouse_id IN
#{warehouseId}
ORDER BY w.warehouse_id FOR SHARE

SELECT z.zone_id, z.warehouse_id, z.parent_zone_id, z.zone_kind, z.lifecycle_status, z.del_flag FROM wms_warehouse_zone z WHERE z.zone_id IN
#{zoneId}
ORDER BY z.zone_id FOR SHARE

SELECT s.storage_id AS space_id, s.warehouse_id AS space_warehouse_id, s.zone_id AS zone_id, s.lifecycle_status AS space_lifecycle_status, s.del_flag AS space_del_flag FROM wms_storage s WHERE s.storage_id IN
#{storageId}
ORDER BY s.storage_id FOR SHARE
